1	/**
2	 * Turning a world into the tiles and wires the canvas draws.
3	 *
4	 * One function, no arithmetic, and nothing invented: every tile below stands
5	 * for a claim the server sent, every wire for an arrow the server sent, and the
6	 * only judgement made here is which tiles there is room to draw.
7	 */
8	
9	import type { Node } from "@xyflow/react";
10	import type { ClaimView, LinkMode, WorldView } from "../world";
11	import type { LayoutEdge, LayoutTile } from "./elkGraph";
12	import { TILE_MIN_HEIGHT, TILE_WIDTH, tileHeight } from "./geometry";
13	import { assignLayers, capLayers } from "./layers";
14	import type { CausalEdge } from "./wires/CausalWire";
15	
16	/** A tile standing for one claim. */
17	export type ClaimNode = Node<
18	  { claim: ClaimView; isHypothesis: boolean; versions?: number; height: number },
19	  "claim"
20	>;
21	
22	/** A tile standing for the claims a column had no room for. */
23	export type OverflowNode = Node<{ count: number }, "overflow">;
24	
25	/** Everything the canvas draws as a box. */
26	export type MapNode = ClaimNode | OverflowNode;
27	
28	/**
29	 * A wire, carrying everything it needs to say its five things at once.
30	 *
31	 * How it is routed is filled in by the canvas rather than here: a wire that has
32	 * to skip a column needs to know where the other tiles ended up, and only the
33	 * canvas knows that.
34	 */
35	export type MapEdge = CausalEdge;
36	
37	/** What the canvas needs in order to draw a world. */
38	export interface MapDrawing {
39	  /** The tiles, without positions — those come from the layout. */
40	  readonly nodes: readonly MapNode[];
41	  /** The wires, as they will be drawn. */
42	  readonly edges: readonly MapEdge[];
43	  /**
44	   * Every tile with the height it will be drawn at, which is the height the
45	   * layout reserves for it. One number, worked out once, used by both.
46	   */
47	  readonly tiles: readonly LayoutTile[];
48	  /**
49	   * The arrows the layout gets a look at.
50	   *
51	   * Not the same list as the wires. Feedback arrows are left out, because a
52	   * left-to-right order cannot be worked out from a map with a loop in it, and
53	   * an arrow that stands in for collapsed tiles is put in, so the collapsed tile
54	   * lands in the column it belongs to.
55	   */
56	  readonly layoutEdges: readonly LayoutEdge[];
57	}
58	
59	/** Which socket a wire of this kind leaves from, and which it arrives at. */
60	function sockets(mode: LinkMode): { source: string; target: string } {
61	  return mode === "sustain"
62	    ? { source: "out-sustain", target: "in-sustain" }
63	    : { source: "out-trigger", target: "in-trigger" };
64	}
65	
66	/**
67	 * What the tile standing in for a column's collapsed claims is called.
68	 *
69	 * The canvas reads the column back out of it, so that activating one of those
70	 * tiles can open the outline filtered to that column — the claims behind it
71	 * already have items there, and the tile only has to point at them.
72	 */
73	export const OVERFLOW_PREFIX = "more-in-column-";
74	
75	/** The identifier of the tile standing in for a column's collapsed claims. */
76	function overflowId(layer: number): string {
77	  return `${OVERFLOW_PREFIX}${layer}`;
78	}
79	
80	/**
81	 * Work out the tiles, the wires, and what the layout gets to see.
82	 *
83	 * @param world The world as the source handed it over.
84	 * @param heights How tall each tile is to be drawn, when something outside knows
85	 *   better than this claim alone does. A diff draws two worlds in one coordinate
86	 *   space, and a claim can need more room in one of them than in the other — it
87	 *   grows badges when an edit touched it — so the box is reserved for the taller
88	 *   of the two and neither painting moves anything. Left out, each tile is as
89	 *   tall as its own content.
90	 */
91	export function toFlow(world: WorldView, heights?: ReadonlyMap<string, number>): MapDrawing {
92	  const ids = world.claims.map((claim) => claim.id);
93	  const { shown, overflows } = capLayers(assignLayers(ids, world.links));
94	  const drawn = new Set(shown.map((one) => one.id));
95	  const byId = new Map(world.claims.map((claim) => [claim.id, claim]));
96	
97	  const nodes: MapNode[] = [];
98	  for (const placed of shown) {
99	    const claim = byId.get(placed.id);
100	    if (claim === undefined) {
101	      continue;
102	    }
103	    nodes.push({
104	      id: claim.id,
105	      type: "claim",
106	      position: { x: 0, y: 0 },
107	      draggable: false,
108	      data: {
109	        claim,
110	        isHypothesis: claim.id === world.hypothesisId,
111	        versions: world.versions,
112	        height: heights?.get(claim.id) ?? tileHeight(claim),
113	      },
114	    });
115	  }
116	  for (const overflow of overflows) {
117	    nodes.push({
118	      id: overflowId(overflow.layer),
119	      type: "overflow",
120	      position: { x: 0, y: 0 },
121	      draggable: false,
122	      data: { count: overflow.count },
123	    });
124	  }
125	
126	  // Only arrows between two tiles that are actually drawn become wires. An
127	  // arrow into a collapsed claim has nowhere to land, and the collapsed tile
128	  // says in words that those claims are still on the map.
129	  const claimWords = new Map(world.claims.map((claim) => [claim.id, claim.claim]));
130	  const edges: MapEdge[] = world.links
131	    .filter((link) => drawn.has(link.source) && drawn.has(link.target))
132	    .map((link) => {
133	      const { source, target } = sockets(link.mode);
134	      return {
135	        id: link.id,
136	        source: link.source,
137	        target: link.target,
138	        sourceHandle: source,
139	        targetHandle: target,
140	        // One kind of wire, drawn by us. How it gets from one end to the other
141	        // is worked out by the canvas, which is the only thing that knows where
142	        // the other tiles ended up.
143	        type: "causal" as const,
144	        // What a reader who never sees the picture hears instead. Everything
145	        // the stroke says, said in words.
146	        ariaLabel:
147	          `arrow from ${claimWords.get(link.source) ?? link.source} ` +
148	          `to ${claimWords.get(link.target) ?? link.target}`,
149	        data: {
150	          shape: link.shape,
151	          strength: link.strength,
152	          mode: link.mode,
153	          lag: link.lag,
154	          reflexive: link.reflexive,
155	          provenance: link.provenance,
156	          conditional: link.conditional,
157	        },
158	      };
159	    });
160	
161	  // What the layout sees. Feedback arrows are set aside: an arrow that points
162	  // backwards cannot help decide what comes first, and leaving it in would make
163	  // the map a loop with no beginning.
164	  const layoutEdges: LayoutEdge[] = world.links
165	    .filter((link) => !link.reflexive && drawn.has(link.source) && drawn.has(link.target))
166	    .map((link) => ({ id: link.id, source: link.source, target: link.target }));
167	
168	  // The collapsed tile is pulled into the right column by the same arrows that
169	  // would have reached the claims it stands for. These are never drawn.
170	  for (const overflow of overflows) {
171	    const hidden = new Set(overflow.hidden);
172	    const causes = new Set(
173	      world.links
174	        .filter((link) => !link.reflexive && hidden.has(link.target) && drawn.has(link.source))
175	        .map((link) => link.source),
176	    );
177	    for (const cause of causes) {
178	      layoutEdges.push({
179	        id: `standing-in:${cause}->${overflowId(overflow.layer)}`,
180	        source: cause,
181	        target: overflowId(overflow.layer),
182	      });
183	    }
184	  }
185	
186	  // **Every tile is told how big it is, and the layout and the drawing library
187	  // are told the same number.**
188	  //
189	  // A tile's box is not something to be discovered: it is 280 pixels wide
190	  // (`TILE_WIDTH`) and exactly as tall as the height this file worked out from
191	  // the claim, and the components draw themselves at precisely that size. The
192	  // layout engine has always been told. The drawing library was not — it was
193	  // left to measure each tile with a `ResizeObserver`, and **it draws nothing
194	  // it has not measured**: a node with no size is rendered `visibility:
195	  // hidden`.
196	  //
197	  // That is a promise the browser does not keep. When too many size
198	  // observations fall due in one frame the browser abandons the rest of them —
199	  // *"a ResizeObserver loop completed with undelivered notifications"* — and an
200	  // abandoned one is never delivered. A tile whose box then never changes size
201	  // again is never observed again, so it stays invisible for the life of the
202	  // page: the map holds its claims, in their places, and a reader cannot see
203	  // them. It is reachable today, on a cold machine, on the stored example.
204	  //
205	  // Saying the size is not a guess and not a duplicate: it is the one number,
206	  // handed to both of the things that need it, from the one place that worked
207	  // it out. The library still measures afterwards and still corrects itself —
208	  // `initialWidth` and `initialHeight` are what it asks for exactly so that a
209	  // caller who knows can say — and nothing downstream reads these back.
210	  const tiles: LayoutTile[] = [];
211	  const sized = nodes.map((node) => {
212	    const height = node.type === "claim" ? node.data.height : TILE_MIN_HEIGHT;
213	    tiles.push({ id: node.id, height });
214	    return { ...node, initialWidth: TILE_WIDTH, initialHeight: height };
215	  }) as MapNode[];
216	
217	  return { nodes: sized, edges, layoutEdges, tiles };
218	}
