// Read-only probe: what does the library's `nodesInitialized` actually depend on?
import { adoptUserNodes } from "/Users/kentgang/git3/katalyst-wt/fix-04-vanishing-wire/frontend/node_modules/@xyflow/system/dist/esm/index.js";

function run(label, nodes, reuse) {
  const lookup = reuse ?? new Map();
  const parents = new Map();
  const out = adoptUserNodes(nodes, lookup, parents, { checkEquality: true });
  const one = lookup.get("H");
  console.log(
    label,
    "-> nodesInitialized:", out.nodesInitialized,
    "| measured:", JSON.stringify(one?.measured),
    "| handleBounds:", one?.internals.handleBounds === undefined ? "undefined" : "present",
  );
  return lookup;
}

// Exactly what toFlow + Canvas hand the library today: initialWidth/initialHeight,
// no `measured`, no `handles`.
const asCanvasBuildsThem = () => [
  { id: "H", type: "claim", position: { x: 0, y: 0 }, data: {}, initialWidth: 280, initialHeight: 120 },
  { id: "C", type: "claim", position: { x: 300, y: 0 }, data: {}, initialWidth: 280, initialHeight: 120 },
];

const lookup = run("1. first setNodes (as Canvas builds them)", asCanvasBuildsThem());

// Now pretend the ResizeObserver delivered: this is what the store's
// updateNodeInternals writes into the lookup.
for (const [id, node] of lookup) {
  lookup.set(id, {
    ...node,
    measured: { width: 280, height: 120 },
    internals: { ...node.internals, handleBounds: { source: [], target: [] } },
  });
}
console.log("   (measurement delivered into the lookup by hand)");

// A re-render: Canvas's `nodes` memo always builds BRAND NEW objects.
run("2. next setNodes, new objects (hover / selection / layout)", asCanvasBuildsThem(), lookup);

// And the same array again, object identity kept (what checkEquality is for).
const same = asCanvasBuildsThem();
const keep = run("3. setNodes, same objects, no measurement yet", same);
for (const [id, node] of keep) {
  keep.set(id, { ...node, measured: { width: 280, height: 120 } });
}
run("4. setNodes, same objects, after measurement", same, keep);

