1	/**
2	 * **Every tile is drawn, and no tile waits to be measured.**
3	 *
4	 * The drawing library draws nothing it has not measured: a node with no size is
5	 * rendered `visibility: hidden`, and it learns the size by watching the element
6	 * change size. That is a promise the browser does not keep. When too many size
7	 * observations fall due in one frame it abandons the rest of them — *"a
8	 * ResizeObserver loop completed with undelivered notifications"* — and an
9	 * abandoned one is never delivered. A tile whose box then never changes size
10	 * again is never observed again, so it stays invisible for the life of the page:
11	 * the map holds its claims, in their places, and a reader cannot see them.
12	 *
13	 * **It is reachable today.** On a cold machine the stored example opens with
14	 * every tile hidden, and the end-to-end test finds it as *"expected visible,
15	 * received hidden"* on `.react-flow__node`. Nothing has to go wrong for a reader
16	 * to meet it; the browser only has to be busy.
17	 *
18	 * We are not guessing at the size. A tile is 280 pixels wide and exactly as tall
19	 * as the height worked out from its claim, the components draw themselves at
20	 * precisely those numbers, and the layout engine is handed the same ones. So the
21	 * fix is to say it: one number, from the one place that worked it out, given to
22	 * both of the things that need it.
23	 *
24	 * Two statements, and the second is the one that matters. Every tile says how
25	 * big it is — and **what it says is the same number the layout was given**,
26	 * because a tile drawn at one size in a space reserved at another is two tiles
27	 * on one spot, which is the collision the layout exists to prevent.
28	 */
29	
30	import { describe, expect, it } from "vitest";
31	import { aClaim, aWire, aWorld } from "../../test/aMap";
32	import { TILE_WIDTH } from "../geometry";
33	import { toFlow } from "../toFlow";
34	
35	/** The stored example's shape, which is the map every browser test opens. */
36	function stored() {
37	  return aWorld({
38	    hypothesisId: "H",
39	    claims: [
40	      aClaim({ id: "H", kind: "hypothesis", claim: "The Strait of Hormuz reopens." }),
41	      aClaim({ id: "C", claim: "Lloyd's war-risk premium falls below 0.4%." }),
42	      aClaim({ id: "B", claim: "Brent crude settles below $68 for five sessions." }),
43	      aClaim({ id: "R", claim: "OPEC+ announces output restraint." }),
44	      aClaim({ id: "M1", kind: "market", claim: "A Polymarket contract resolves YES." }),
45	    ],
46	    links: [
47	      aWire({ source: "H", target: "C" }),
48	      aWire({ source: "C", target: "B" }),
49	      aWire({ source: "B", target: "M1" }),
50	    ],
51	  });
