      `point ${on === null ? "none on the glass" : `${Math.round(on.x)},${Math.round(on.y)}`}` +
        ` · keyboard ${standingOnIt ?? "off the map"} · panel "${said.slice(0, 70)}"`,
    );
    await page.waitForTimeout(250);
